package com.vibeguard.samples.admin;
import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
/** Protects staff-only user administration with an environment-provided API key. */ @RestController @RequestMapping("/internal/admin") public class AdminController { private final Map<Long,User> users=new ConcurrentHashMap<>(); @Value("${ADMIN_API_KEY:}") private String adminApiKey; public AdminController(){users.put(1L,new User(1,"member-one@example.invalid",true));users.put(2L,new User(2,"member-two@example.invalid",true));} @GetMapping("/users") public ResponseEntity<Collection<User>> users(@RequestHeader("X-Admin-Key") String key){return authorized(key)?ResponseEntity.ok(users.values()):ResponseEntity.status(401).build();} @PostMapping("/users/{id}/deactivate") public ResponseEntity<User> deactivate(@RequestHeader("X-Admin-Key") String key,@PathVariable long id){if(!authorized(key))return ResponseEntity.status(401).build();User user=users.get(id);if(user==null)return ResponseEntity.notFound().build();User disabled=new User(user.id(),user.email(),false);users.put(id,disabled);return ResponseEntity.ok(disabled);} @GetMapping("/stats") public ResponseEntity<Stats> stats(@RequestHeader("X-Admin-Key") String key){if(!authorized(key))return ResponseEntity.status(401).build();long active=users.values().stream().filter(User::active).count();return ResponseEntity.ok(new Stats(users.size(),active));} private boolean authorized(String key){return !adminApiKey.isBlank()&&adminApiKey.equals(key);} record User(long id,String email,boolean active){} record Stats(long registeredUsers,long activeUsers){} }
